// Type-aware Extended C++ member dispatch.
template <class EcppSelf, class... EcppArgs>
decltype(auto) __ecpp_dispatch_add(EcppSelf&& self, EcppArgs&&... args) {
    if constexpr (requires {
        __ecpp_additional_add(
            std::forward<EcppSelf>(self),
            std::forward<EcppArgs>(args)...
        );
    }) {
        return __ecpp_additional_add(
            std::forward<EcppSelf>(self),
            std::forward<EcppArgs>(args)...
        );
    } else if constexpr (requires {
        __ecpp_additional_add(
            self,
            std::forward<EcppArgs>(args)...
        );
    }) {
        return __ecpp_additional_add(
            self,
            std::forward<EcppArgs>(args)...
        );
    } else {
        return std::forward<EcppSelf>(self).add(
            std::forward<EcppArgs>(args)...
        );
    }
}

